
package ma.um6p.compusconnect;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Column;
// Represents one campus information item stored in the database.
@Entity
public class CampusInfo {
    // Unique identifier automatically generated by the database.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    // The name or title of the campus information.
    @Column(nullable = false)
    private String title;
    // Detailed explanation of the information.
    @Column(length = 2000)
    private String description;
    // Category used to organize campus information.
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private CampusInfoCategory category;
    // Physical location of the facility or service.
    private String location;
    // Opening hours, if applicable.
    private String openingHours;
    // Contact information, if available.
    private String contactInfo;
    // Website URL, if available.
    private String websiteUrl;
    // Default constructor required by JPA.
    public CampusInfo() {
    }
    // Constructor used to create a campus information item.
    public CampusInfo(String title, String description,
                      CampusInfoCategory category, String location,
                      String openingHours, String contactInfo,
                      String websiteUrl) {
        this.title = title;
        this.description = description;
        this.category = category;
        this.location = location;
        this.openingHours = openingHours;
        this.contactInfo = contactInfo;
        this.websiteUrl = websiteUrl;
    }
    // Returns the ID of this campus information item.
    public Long getId() {
        return id;
    }
    // Returns its title.
    public String getTitle() {
        return title;
    }
    // Returns its description.
    public String getDescription() {
        return description;
    }
    // Returns its category.
    public CampusInfoCategory getCategory() {
        return category;
    }
    // Returns its location.
    public String getLocation() {
        return location;
    }

    // Returns its opening hours.
    public String getOpeningHours() {
        return openingHours;
    }

    // Returns its contact information.
    public String getContactInfo() {
        return contactInfo;
    }
    // Returns its website URL.
    public String getWebsiteUrl() {
        return websiteUrl;
    }
    // Updates the title.
    public void setTitle(String title) {
        this.title = title;
    }
    // Updates the description.
    public void setDescription(String description) {
        this.description = description;
    }
    // Updates the category.
    public void setCategory(CampusInfoCategory category) {
        this.category = category;
    }

    // Updates the location.
    public void setLocation(String location) {
        this.location = location;
    }

    // Updates the opening hours.
    public void setOpeningHours(String openingHours) {
        this.openingHours = openingHours;
    }

    // Updates contact information.
    public void setContactInfo(String contactInfo) {
        this.contactInfo = contactInfo;
    }

    // Updates the website URL.
    public void setWebsiteUrl(String websiteUrl) {
        this.websiteUrl = websiteUrl;
    }
}

